def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    k = 3  # Define the sliding window size
    rolling_maxs = []  # Initialize list to store rolling maximums

    for i in range(len(numbers) - k + 1):
        window = numbers[i:i+k]
        max_val = max(window)
        rolling_maxs.append(max_val)

    return rolling_maxs

